def compile_run(directory, edits=None):
    work=Path(directory); sources=dict(STUBS);sources['ls/augment/com/TestExtraction.java']=TEST
    for p in FILES: sources['ls/augment/com/'+p.name]=(edits or {}).get(p.name,p.read_text(encoding='utf-8'))
    paths=[]
    for name,value in sources.items():
        p=work/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(value,encoding='utf-8');paths.append(str(p))
    c=subprocess.run([str(JDK/'javac.exe'),'-J-Dfile.encoding=UTF-8','-J-Duser.language=en','--release','17','-encoding','UTF-8','-d',str(work/'classes'),*paths],capture_output=True,text=True,encoding='utf-8',errors='replace',timeout=40)
    if c.returncode: raise AssertionError(c.stdout+c.stderr)
    return subprocess.run([str(JDK/'java.exe'),'-Dfile.encoding=UTF-8','-Duser.language=en','-cp',str(work/'classes'),'ls.augment.com.TestExtraction'],capture_output=True,text=True,encoding='utf-8',errors='replace',timeout=30)

def sdk():
    cp=[ROOT/'audit-output/android-sdk/platforms/android-36/android.jar',ROOT/'android/app/build/intermediates/javac/debug/compileDebugJavaWithJavac/classes',
        ROOT/'android/app/build/intermediates/compile_and_runtime_not_namespaced_r_class_jar/debug/processDebugResources/R.jar']
    files=list(dict.fromkeys(FILES+sorted(SRC.glob('AtomicWorkbenchExtraction*.java'))+[SRC/'UiKit.java',SRC/'AtomicWorkbenchTextTool.java']))
    with tempfile.TemporaryDirectory(prefix='duo-extract-sdk-') as d:
        r=subprocess.run([str(JDK/'javac.exe'),'-J-Dfile.encoding=UTF-8','-J-Duser.language=en','-encoding','UTF-8','-source','17','-target','17','-Xlint:-options','-cp',os.pathsep.join(map(str,cp)),'-d',d,*map(str,files)],capture_output=True,text=True,encoding='utf-8',errors='replace',timeout=40)
        if r.returncode: raise AssertionError(r.stdout+r.stderr)
    print('PASS SDK36 complete extraction production chain + unchanged paste models/service')

def main():
    parser=argparse.ArgumentParser();parser.add_argument('--negative-controls',action='store_true');args=parser.parse_args()
    with tempfile.TemporaryDirectory(prefix='duo-extract-') as d:
        r=compile_run(d)
        if r.returncode:raise AssertionError(r.stdout+r.stderr)
        print(r.stdout,end='')
    sdk()
    if args.negative_controls:
        negatives=[
            ('AtomicWorkbenchExtractionEngine.java','||!authority.validate(request,proof))throw','||false)throw','system lease not checked before and after read'),
            ('AtomicWorkbenchExtractionAuthority.java','&&p.sameSource(current);',';','reused display unique accepted'),
            ('AtomicWorkbenchExtractionAccessibilitySource.java','if(m.protectedNode())','if(false)','protected subtree read before metadata gate'),
            ('AtomicWorkbenchExtractionAccessibilitySource.java','if(life!=lifecycle||epoch!=epoch(window))','if(false)','source epoch ignored inside production traversal'),
            ('AtomicWorkbenchExtractionEngine.java','&&(cancelled||owner.closed||!request.fresh(SystemClock.elapsedRealtime())','&&(false||false||!request.fresh(SystemClock.elapsedRealtime())','late cancelled UI received content'),
        ]
        for filename,before,after,witness in negatives:
            original=(SRC/filename).read_text(encoding='utf-8');assert original.count(before)==1,(filename,before)
            with tempfile.TemporaryDirectory(prefix='duo-extract-negative-') as d:
                r=compile_run(d,{filename:original.replace(before,after)})
                if r.returncode==0 or witness not in r.stdout+r.stderr:raise AssertionError(r.stdout+r.stderr)
                print('PASS extraction behavior negative: '+filename+' / '+witness)
    print('PENDING SYSTEM HOOK/POINTER/UI INTEGRATION AND PHONE ACCEPTANCE; NO ADB/GRADLE')

if __name__=='__main__':main()
